package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	_ "github.com/shopspring/decimal"
)

// DateRec 01 DATE-REC, 12 bytes
type DateRec struct {
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items
var WsEofFlag string // PIC X len=1 = "N"
var WsLeapFlag string // PIC X len=1 = "N"
var WsQ int64      // PIC 9(4)
var WsR4 int64     // PIC 9(3)
var WsR100 int64   // PIC 9(3)
var WsR400 int64   // PIC 9(3)
var WsMaxDay int64 // PIC 99
var WsValid int64  // PIC 99
var WsBadMonth int64
var WsBadDay int64

var dateRec DateRec

var dateFile *os.File
var scanner *bufio.Scanner
var eofReached bool

func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func truncPic9(v int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := pow10(digits)
	// keep low-order digits, for positive values mod
	// for negative, COBOL keeps sign and low-order absolute? not needed here
	if v >= 0 {
		return v % mod
	}
	// handle negative: truncate toward zero to low-order digits
	av := -v % mod
	return -av
}

func parseNum(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	// s should be digits, possibly with leading zeros
	// if contains non-digit, try to parse as is
	var v int64
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			v = v*10 + int64(ch-'0')
		} else {
			// non-digit treated as 0? but attempt Atoi fallback
			return 0
		}
	}
	return v
}

func formatPic9(v int64, width int) string {
	// unedited numeric: zero-padded to width
	// v is already truncated to fit, may be negative (not expected)
	if v < 0 {
		// for negative, format with sign then zeros?
		// PIC 9 is unsigned in this program, ignore
		return fmt.Sprintf("%0*d", width, v)
	}
	return fmt.Sprintf("%0*d", width, v)
}

// helpers for flags
func isInputDone() bool { return WsEofFlag == "Y" }
func isLeap() bool      { return WsLeapFlag == "Y" }

func main() {
	MAIN_PARA()
}

// paragraph functions

func MAIN_PARA() {
	// init working-storage defaults
	WsEofFlag = "N"
	WsLeapFlag = "N"
	WsQ = 0
	WsR4 = 0
	WsR100 = 0
	WsR400 = 0
	WsMaxDay = 0
	WsValid = 0
	WsBadMonth = 0
	WsBadDay = 0

	// OPEN INPUT DATE-FILE
	var err error
	dateFile, err = os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty? COBOL would error
		// create empty scanner that immediately EOF
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer dateFile.Close()
	scanner = bufio.NewScanner(dateFile)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 10*1024*1024)
	eofReached = false

	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	// CLOSE DATE-FILE (defer)
	// DISPLAY "VALID: " WS-VALID " BAD MONTH: " WS-BAD-MONTH " BAD DAY: " WS-BAD-DAY
	line := "VALID: " + formatPic9(WsValid, 2) + " BAD MONTH: " + formatPic9(WsBadMonth, 2) + " BAD DAY: " + formatPic9(WsBadDay, 2)
	fmt.Fprintln(os.Stdout, line)
}

func READ_PARA() {
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if scanner.Scan() {
		raw := scanner.Text()
		// strip trailing \r if present (LINE SEQUENTIAL may have CRLF)
		if len(raw) > 0 && raw[len(raw)-1] == '\r' {
			raw = raw[:len(raw)-1]
		}
		// pad with spaces on right to 12 bytes if shorter
		if len(raw) < 12 {
			raw = raw + strings.Repeat(" ", 12-len(raw))
		} else if len(raw) > 12 {
			raw = raw[:12]
		}
		// parse into dateRec
		dtId := raw[0:4]
		dtYyyyStr := raw[4:8]
		dtMmStr := raw[8:10]
		dtDdStr := raw[10:12]

		dateRec.DtId = dtId
		dateRec.DtYyyy = parseNum(dtYyyyStr)
		dateRec.DtMm = parseNum(dtMmStr)
		dateRec.DtDd = parseNum(dtDdStr)
	} else {
		// AT END
		WsEofFlag = "Y"
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
		}
	}
}

func PROCESS_PARA() {
	LEAP_PARA()
	// EVALUATE TRUE
	if dateRec.DtMm < 1 || dateRec.DtMm > 12 {
		WsBadMonth = truncPic9(WsBadMonth+1, 2)
		// DISPLAY DT-ID " BAD MONTH " DT-MM
		line := dateRec.DtId + " BAD MONTH " + formatPic9(dateRec.DtMm, 2)
		fmt.Fprintln(os.Stdout, line)
	} else {
		DAYS_PARA()
		if dateRec.DtDd < 1 || dateRec.DtDd > WsMaxDay {
			WsBadDay = truncPic9(WsBadDay+1, 2)
			line := dateRec.DtId + " BAD DAY " + formatPic9(dateRec.DtDd, 2) + " MAX " + formatPic9(WsMaxDay, 2)
			fmt.Fprintln(os.Stdout, line)
		} else {
			WsValid = truncPic9(WsValid+1, 2)
			line := dateRec.DtId + " VALID " + formatPic9(dateRec.DtYyyy, 4) + "-" + formatPic9(dateRec.DtMm, 2) + "-" + formatPic9(dateRec.DtDd, 2)
			fmt.Fprintln(os.Stdout, line)
		}
	}
	READ_PARA()
}

func LEAP_PARA() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4
	// etc.
	if 4 != 0 {
		q := dateRec.DtYyyy / 4
		r := dateRec.DtYyyy - q*4
		WsQ = truncPic9(q, 4)
		WsR4 = truncPic9(r, 3)
	}
	if 100 != 0 {
		q := dateRec.DtYyyy / 100
		r := dateRec.DtYyyy - q*100
		WsQ = truncPic9(q, 4)
		WsR100 = truncPic9(r, 3)
	}
	if 400 != 0 {
		q := dateRec.DtYyyy / 400
		r := dateRec.DtYyyy - q*400
		WsQ = truncPic9(q, 4)
		WsR400 = truncPic9(r, 3)
	}
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYS_PARA() {
	switch dateRec.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = truncPic9(29, 2)
		} else {
			WsMaxDay = truncPic9(28, 2)
		}
	case 4, 6, 9, 11:
		WsMaxDay = truncPic9(30, 2)
	default:
		WsMaxDay = truncPic9(31, 2)
	}
}
